219: #if PRECISE_GETTIME && HAVE_NANOSLEEP
220:   retry:
221: #endif
222:     starttime = _nc_gettime(&t0, TRUE);
223: 
224:     count = 0;
225:     (void) count;
226: 
227: #ifdef NCURSES_WGETCH_EVENTS
228:     if ((mode & TW_EVENT) && evl)
229: 	evl->result_flags = 0;
230: #endif
231: 
232: #if USE_FUNC_POLL
233:     memset(fd_list, 0, sizeof(fd_list));
234: 
235: #ifdef NCURSES_WGETCH_EVENTS
236:     if ((mode & TW_EVENT) && evl) {
237: 	if (fds == fd_list)
238: 	    fds = typeMalloc(struct pollfd, MIN_FDS + evl->count);
239: 	if (fds == NULL)
240: 	    return TW_NONE;
241:     }
242: #endif
243: 
244:     if (mode & TW_INPUT) {
245: 	fds[count].fd = sp->_ifd;
246: 	fds[count].events = POLLIN;
247: 	count++;
248:     }
249:     if ((mode & TW_MOUSE)
250: 	&& (fd = sp->_mouse_fd) >= 0) {
251: 	fds[count].fd = fd;
252: 	fds[count].events = POLLIN;
253: 	count++;
254:     }
255: #ifdef NCURSES_WGETCH_EVENTS
256:     if ((mode & TW_EVENT) && evl) {
257: 	for (n = 0; n < evl->count; ++n) {
258: 	    _nc_event *ev = evl->events[n];
259: 
260: 	    if (ev->type == _NC_EVENT_FILE
261: 		&& (ev->data.fev.flags & _NC_EVENT_FILE_READABLE)) {
262: 		fds[count].fd = ev->data.fev.fd;
263: 		fds[count].events = POLLIN;
264: 		count++;
265: 	    }
266: 	}
267:     }
268: #endif
269: 
270:     result = (int) poll(fds, (size_t) count, milliseconds);
271: 
272: #ifdef NCURSES_WGETCH_EVENTS
273:     if ((mode & TW_EVENT) && evl) {
274: 	int c;
275: 
276: 	if (!result)
277: 	    count = 0;
278: 
279: 	for (n = 0; n < evl->count; ++n) {
280: 	    _nc_event *ev = evl->events[n];
281: 
282: 	    if (ev->type == _NC_EVENT_FILE
283: 		&& (ev->data.fev.flags & _NC_EVENT_FILE_READABLE)) {
284: 		ev->data.fev.result = 0;
285: 		for (c = 0; c < count; c++)
286: 		    if (fds[c].revents & POLLNVAL) {
287: 			errno = EBADF;
288: 		    } else if (fds[c].fd == ev->data.fev.fd
289: 			       && fds[c].revents & POLLIN) {
290: 			ev->data.fev.result |= _NC_EVENT_FILE_READABLE;
291: 			evl->result_flags |= _NC_EVENT_FILE_READABLE;
292: 		    }
293: 	    } else if (ev->type == _NC_EVENT_TIMEOUT_MSEC
294: 		       && !result && timeout_is_event) {
295: 		evl->result_flags |= _NC_EVENT_TIMEOUT_MSEC;
296: 	    }
297: 	}
298:     }
299: #endif
300: 
301: #elif defined(__BEOS__)
302:     /*
303:      * BeOS's select() is declared in socket.h, so the configure script does
304:      * not see it.  That's just as well, since that function works only for
305:      * sockets.  This (using snooze and ioctl) was distilled from Be's patch
306:      * for ncurses which uses a separate thread to simulate select().
307:      *
308:      * FIXME: the return values from the ioctl aren't very clear if we get
309:      * interrupted.
310:      *
311:      * FIXME: this assumes mode&1 if milliseconds < 0 (see lib_getch.c).
312:      */
313:     result = TW_NONE;
314:     if (mode & TW_INPUT) {
315: 	int step = (milliseconds < 0) ? 0 : 5000;
316: 	bigtime_t d;
317: 	bigtime_t useconds = milliseconds * 1000;
318: 	int n, howmany;
319: 
320: 	if (useconds <= 0)	/* we're here to go _through_ the loop */
321: 	    useconds = 1;
322: 
323: 	for (d = 0; d < useconds; d += step) {
324: 	    n = 0;
325: 	    howmany = ioctl(0, 'ichr', &n);
326: 	    if (howmany >= 0 && n > 0) {
327: 		result = 1;
328: 		break;
329: 	    }
330: 	    if (useconds > 1 && step > 0) {
331: 		snooze(step);
332: 		milliseconds -= (step / 1000);
333: 		if (milliseconds <= 0) {
334: 		    milliseconds = 0;
335: 		    break;
336: 		}
337: 	    }
338: 	}
339:     } else if (milliseconds > 0) {
340: 	snooze(milliseconds * 1000);
341: 	milliseconds = 0;
342:     }
343: #elif HAVE_SELECT
344:     /*
345:      * select() modifies the fd_set arguments; do this in the
346:      * loop.
347:      */
