349: 
350: #if !USE_KLIBC_KBD
351:     if (mode & TW_INPUT) {
352: 	FD_SET(sp->_ifd, &set);
353: 	count = sp->_ifd + 1;
354:     }
355: #endif
356:     if ((mode & TW_MOUSE)
357: 	&& (fd = sp->_mouse_fd) >= 0) {
358: 	FD_SET(fd, &set);
359: 	count = Max(fd, count) + 1;
360:     }
361: #ifdef NCURSES_WGETCH_EVENTS
362:     if ((mode & TW_EVENT) && evl) {
363: 	for (n = 0; n < evl->count; ++n) {
364: 	    _nc_event *ev = evl->events[n];
365: 
366: 	    if (ev->type == _NC_EVENT_FILE
367: 		&& (ev->data.fev.flags & _NC_EVENT_FILE_READABLE)) {
368: 		FD_SET(ev->data.fev.fd, &set);
369: 		count = Max(ev->data.fev.fd + 1, count);
370: 	    }
371: 	}
372:     }
373: #endif
