395: 	    result = 0;
396: 	    break;
397: 	}
398:     }
399: #else
400:     if (milliseconds >= 0) {
401: 	struct timeval ntimeout;
402: 	ntimeout.tv_sec = milliseconds / 1000;
403: 	ntimeout.tv_usec = (milliseconds % 1000) * 1000;
404: 	result = select(count, &set, NULL, NULL, &ntimeout);
405:     } else {
406: 	result = select(count, &set, NULL, NULL, NULL);
407:     }
408: #endif
409: 
410: #ifdef NCURSES_WGETCH_EVENTS
411:     if ((mode & TW_EVENT) && evl) {
412: 	evl->result_flags = 0;
413: 	for (n = 0; n < evl->count; ++n) {
414: 	    _nc_event *ev = evl->events[n];
415: 
416: 	    if (ev->type == _NC_EVENT_FILE
417: 		&& (ev->data.fev.flags & _NC_EVENT_FILE_READABLE)) {
418: 		ev->data.fev.result = 0;
419: 		if (FD_ISSET(ev->data.fev.fd, &set)) {
420: 		    ev->data.fev.result |= _NC_EVENT_FILE_READABLE;
421: 		    evl->result_flags |= _NC_EVENT_FILE_READABLE;
422: 		}
423: 	    } else if (ev->type == _NC_EVENT_TIMEOUT_MSEC
424: 		       && !result && timeout_is_event)
425: 		evl->result_flags |= _NC_EVENT_TIMEOUT_MSEC;
426: 	}
427:     }
428: #endif
