432:     returntime = _nc_gettime(&t0, FALSE);
433: 
434:     if (milliseconds >= 0)
435: 	milliseconds -= (int) (returntime - starttime);
436: 
437: #ifdef NCURSES_WGETCH_EVENTS
438:     if (evl) {
439: 	evl->result_flags = 0;
440: 	for (n = 0; n < evl->count; ++n) {
441: 	    _nc_event *ev = evl->events[n];
442: 
443: 	    if (ev->type == _NC_EVENT_TIMEOUT_MSEC) {
444: 		long diff = (returntime - starttime);
445: 		if (ev->data.timeout_msec <= diff)
446: 		    ev->data.timeout_msec = 0;
447: 		else
448: 		    ev->data.timeout_msec -= diff;
449: 	    }
450: 
451: 	}
452:     }
453: #endif
454: 
455: #if PRECISE_GETTIME && HAVE_NANOSLEEP
456:     /*
457:      * If the timeout hasn't expired, and we've gotten no data,
458:      * this is probably a system where 'select()' needs to be left
459:      * alone so that it can complete.  Make this process sleep,
460:      * then come back for more.
461:      */
462:     if (result == 0 && milliseconds > 100) {
463: 	napms(100);		/* FIXME: this won't be right if I recur! */
464: 	milliseconds -= 100;
465: 	goto retry;
466:     }
467: #endif
468: 
469:     /* return approximate time left in milliseconds */
470:     if (timeleft)
471: 	*timeleft = milliseconds;
472: 
473:     TR(TRACE_IEVENT, ("end twait: returned %d (%d), remaining time %d msec",
474: 		      result, errno, milliseconds));
475: 
476:     /*
477:      * Both 'poll()' and 'select()' return the number of file descriptors
478:      * that are active.  Translate this back to the mask that denotes which
479:      * file-descriptors, so that we don't need all of this system-specific
480:      * code everywhere.
481:      */
482:     if (result != 0) {
483: 	int valid_fds = result;
484: 	(void) valid_fds;
485: 	if (result > 0) {
486: 	    result = 0;
487: #if USE_FUNC_POLL
488: 	    for (count = 0; count < MIN_FDS; count++) {
489: 		if (fds[count].revents & POLLNVAL) {
490: 		    valid_fds--;
491: 		    errno = EBADF;
492: 		} else if ((mode & (1 << count))
493: 			   && (fds[count].revents & POLLIN)) {
494: 		    result |= (1 << count);
495: 		}
496: 	    }
497: 	    if (!valid_fds && milliseconds)
498: 		napms(milliseconds);
499: #elif defined(__BEOS__)
500: 	    result = TW_INPUT;	/* redundant, but simple */
501: #elif HAVE_SELECT
502: 	    if ((mode & TW_MOUSE)
503: 		&& (fd = sp->_mouse_fd) >= 0
504: 		&& FD_ISSET(fd, &set))
505: 		result |= TW_MOUSE;
506: 	    if ((mode & TW_INPUT)
507: 		&& FD_ISSET(sp->_ifd, &set))
508: 		result |= TW_INPUT;
509: #endif
510: 	} else
511: 	    result = 0;
512:     }
513: #ifdef NCURSES_WGETCH_EVENTS
514:     if ((mode & TW_EVENT) && evl && evl->result_flags)
515: 	result |= TW_EVENT;
516: #endif
517: 
518: #if USE_FUNC_POLL
519: #ifdef NCURSES_WGETCH_EVENTS
520:     if (fds != fd_list)
521: 	free((char *) fds);
522: #endif
523: #endif
524: 
525:     return (result);
